  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-soft: #f8fafc;
      --text: #101828;
      --muted: #667085;
      --border: #e4e7ec;
      --danger: #dc2626;
      --danger-dark: #b91c1c;
      --danger-soft: #fef2f2;
      --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
      --radius-lg: 28px;
      --radius-md: 18px;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(99, 102, 241, 0.16), transparent 34rem),
        linear-gradient(135deg, #f8fbff 0%, var(--bg) 52%, #eef2ff 100%);
    }

    button {
      font: inherit;
    }

    .app-shell {
      width: min(1120px, calc(100% - 32px));
      margin: 0 auto;
      padding: 40px 0;
    }

    .top-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 20px;
      margin-bottom: 28px;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      letter-spacing: -0.03em;
    }

    .brand-mark {
      display: grid;
      width: 42px;
      height: 42px;
      place-items: center;
      color: #ffffff;
      background: linear-gradient(135deg, #111827, #4f46e5);
      border-radius: 14px;
      box-shadow: 0 12px 30px rgba(79, 70, 229, 0.28);
    }

    .library-link {
      color: var(--muted);
      text-decoration: none;
      font-size: 0.95rem;
      font-weight: 650;
    }

    .preview-card {
      display: grid;
      grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.65fr);
      gap: 28px;
      padding: 22px;
      background: rgba(255, 255, 255, 0.84);
      border: 1px solid rgba(255, 255, 255, 0.72);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .image-frame {
      overflow: hidden;
      min-height: 560px;
      background: #111827;
      border-radius: 24px;
      box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
    }

    .preview-image {
      display: block;
      width: 100%;
      height: 100%;
      min-height: 560px;
      object-fit: cover;
    }

    .details-panel {
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 24px;
      padding: 10px 6px 6px;
    }

    .eyebrow {
      margin: 0 0 10px;
      color: #4f46e5;
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.1rem, 4vw, 4rem);
      line-height: 0.98;
      letter-spacing: -0.07em;
    }

    .description {
      max-width: 28rem;
      margin: 18px 0 0;
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.7;
    }

    .meta-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      margin-top: 28px;
    }

    .meta-item {
      padding: 14px;
      background: var(--surface-soft);
      border: 1px solid var(--border);
      border-radius: 16px;
    }

    .meta-label {
      display: block;
      margin-bottom: 6px;
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
    }

    .meta-value {
      font-weight: 760;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 12px;
      padding-top: 12px;
      border-top: 1px solid var(--border);
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      min-height: 46px;
      padding: 0 18px;
      border: 0;
      border-radius: 999px;
      cursor: pointer;
      font-weight: 780;
      transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible,
    .icon-button:focus-visible {
      outline: 4px solid rgba(79, 70, 229, 0.2);
      outline-offset: 3px;
    }

    .button-primary {
      color: #ffffff;
      background: #111827;
      box-shadow: 0 12px 24px rgba(17, 24, 39, 0.18);
    }

    .button-danger-soft {
      color: var(--danger);
      background: var(--danger-soft);
      box-shadow: inset 0 0 0 1px rgba(220, 38, 38, 0.12);
    }

    .button-danger {
      color: #ffffff;
      background: var(--danger);
      box-shadow: 0 12px 28px rgba(220, 38, 38, 0.28);
    }

    .button-danger:hover {
      background: var(--danger-dark);
    }

    .button-secondary {
      color: #344054;
      background: #ffffff;
      box-shadow: inset 0 0 0 1px var(--border);
    }

    .modal-root {
      position: fixed;
      inset: 0;
      z-index: 10;
      display: none;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .modal-root.is-open {
      display: flex;
    }

    .modal-backdrop {
      position: absolute;
      inset: 0;
      background: rgba(15, 23, 42, 0.56);
      backdrop-filter: blur(8px);
    }

    .dialog {
      position: relative;
      width: min(100%, 460px);
      padding: 24px;
      background: var(--surface);
      border: 1px solid rgba(255, 255, 255, 0.72);
      border-radius: 26px;
      box-shadow: 0 30px 90px rgba(15, 23, 42, 0.32);
      animation: dialog-in 180ms ease-out;
    }

    @keyframes dialog-in {
      from {
        opacity: 0;
        transform: translateY(12px) scale(0.98);
      }

      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    .dialog-header {
      display: flex;
      align-items: flex-start;
      gap: 16px;
    }

    .warning-icon {
      display: grid;
      flex: 0 0 auto;
      width: 48px;
      height: 48px;
      place-items: center;
      color: var(--danger);
      background: var(--danger-soft);
      border-radius: 16px;
    }

    .dialog-title {
      margin: 0;
      font-size: 1.35rem;
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin: 8px 0 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .icon-button {
      display: grid;
      flex: 0 0 auto;
      width: 38px;
      height: 38px;
      margin-left: auto;
      place-items: center;
      color: var(--muted);
      background: #ffffff;
      border: 1px solid var(--border);
      border-radius: 999px;
      cursor: pointer;
    }

    .dialog-preview {
      display: flex;
      align-items: center;
      gap: 12px;
      margin: 22px 0;
      padding: 12px;
      background: var(--surface-soft);
      border: 1px solid var(--border);
      border-radius: 18px;
    }

    .dialog-thumbnail {
      width: 58px;
      height: 58px;
      object-fit: cover;
      border-radius: 14px;
    }

    .dialog-image-name {
      margin: 0 0 4px;
      font-weight: 780;
    }

    .dialog-image-meta {
      margin: 0;
      color: var(--muted);
      font-size: 0.9rem;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    @media (max-width: 800px) {
      .app-shell {
        padding: 20px 0;
      }

      .preview-card {
        grid-template-columns: 1fr;
      }

      .image-frame,
      .preview-image {
        min-height: 360px;
      }

      .details-panel {
        padding: 0;
      }
    }

    @media (max-width: 520px) {
      .top-bar,
      .actions,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .button {
        width: 100%;
      }

      .meta-grid {
        grid-template-columns: 1fr;
      }

      .dialog {
        padding: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const image = {
      title: "Alpine Morning",
      location: "Dolomites, Italy",
      date: "May 12, 2026",
      size: "4.8 MB",
      src: "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=85",
      alt: "A quiet mountain lake reflecting evergreen trees and misty alpine peaks"
    };

    function Button({ className = "", children, type = "button", ariaLabel = "" }) {
      const aria = ariaLabel ? ` aria-label="${ariaLabel}"` : "";
      return `<button class="button ${className}" type="${type}"${aria}>${children}</button>`;
    }

    function Header() {
      return `
        <header class="top-bar">
          <div class="brand">
            <span class="brand-mark" aria-hidden="true">✦</span>
            <span>Frame Library</span>
          </div>
          <a class="library-link" href="#" aria-label="Return to image library">Back to library</a>
        </header>
      `;
    }

    function ImagePreview({ image }) {
      return `
        <main class="preview-card">
          <section class="image-frame" aria-label="Image preview">
            <img class="preview-image" src="${image.src}" alt="${image.alt}">
          </section>

          <aside class="details-panel" aria-label="Image details">
            <div>
              <p class="eyebrow">Image preview</p>
              <h1>${image.title}</h1>
              <p class="description">
                A saved library image ready for use in campaigns, moodboards, and product stories.
                Review the details or remove it from your library.
              </p>

              <div class="meta-grid">
                <div class="meta-item">
                  <span class="meta-label">Location</span>
                  <span class="meta-value">${image.location}</span>
                </div>
                <div class="meta-item">
                  <span class="meta-label">Added</span>
                  <span class="meta-value">${image.date}</span>
                </div>
                <div class="meta-item">
                  <span class="meta-label">Format</span>
                  <span class="meta-value">JPEG</span>
                </div>
                <div class="meta-item">
                  <span class="meta-label">Size</span>
                  <span class="meta-value">${image.size}</span>
                </div>
              </div>
            </div>

            <div class="actions">
              ${Button({ className: "button-primary", children: "Download" })}
              ${Button({ className: "button-danger-soft trigger", children: "Delete image", ariaLabel: "Delete image from library" })}
            </div>
          </aside>
        </main>
      `;
    }

    function DeleteDialog({ image }) {
      return `
        <div class="modal-root" id="deleteModal" role="presentation" aria-hidden="true">
          <div class="modal-backdrop" data-close-modal></div>
          <section class="dialog" role="dialog" aria-modal="true" aria-labelledby="deleteDialogTitle" aria-describedby="deleteDialogDescription" tabindex="-1">
            <div class="dialog-header">
              <span class="warning-icon" aria-hidden="true">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
                  <path d="M12 9v4m0 4h.01M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                </svg>
              </span>
              <div>
                <h2 class="dialog-title" id="deleteDialogTitle">Delete this image?</h2>
                <p class="dialog-copy" id="deleteDialogDescription">
                  This will remove the image from your library. This action cannot be undone.
                </p>
              </div>
              <button class="icon-button" type="button" data-close-modal aria-label="Close dialog">
                <svg width="18" height="18" viewBox="0 0 20 20" fill="none" aria-hidden="true">
                  <path d="m5 5 10 10M15 5 5 15" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                </svg>
              </button>
            </div>

            <div class="dialog-preview">
              <img class="dialog-thumbnail" src="${image.src}" alt="">
              <div>
                <p class="dialog-image-name">${image.title}</p>
                <p class="dialog-image-meta">${image.location} · ${image.size}</p>
              </div>
            </div>

            <div class="dialog-actions">
              ${Button({ className: "button-secondary", children: "Cancel" })}
              ${Button({ className: "button-danger", children: "Yes, delete image" })}
            </div>
          </section>
        </div>
      `;
    }

    function App() {
      return `
        <div class="app-shell">
          ${Header()}
          ${ImagePreview({ image })}
        </div>
        ${DeleteDialog({ image })}
      `;
    }

    document.getElementById("app").innerHTML = App();

    const modal = document.getElementById("deleteModal");
    const dialog = modal.querySelector(".dialog");
    const trigger = document.querySelector(".trigger");
    const closeControls = modal.querySelectorAll("[data-close-modal], .button-secondary, .button-danger");

    function openModal() {
      modal.classList.add("is-open");
      modal.setAttribute("aria-hidden", "false");
      dialog.focus();
    }

    function closeModal() {
      modal.classList.remove("is-open");
      modal.setAttribute("aria-hidden", "true");
      trigger.focus();
    }

    trigger.addEventListener("click", openModal);
    closeControls.forEach((control) => control.addEventListener("click", closeModal));

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && modal.classList.contains("is-open")) {
        closeModal();
      }
    });
  </script>
</body>
</html>
