       --radius-md: 18px;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
     }

     * {
       box-sizing: border-box;
     }

     body {
       min-height: 100vh;
       margin: 0;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(99, 102, 241, 0.16), transparent 34rem),
         linear-gradient(135deg, #f8fbff 0%, var(--bg) 52%, #eef2ff 100%);
     }

     button {
       font: inherit;
     }

     .app-shell {
       width: min(1120px, calc(100% - 32px));
       margin: 0 auto;
       padding: 40px 0;
     }

     .top-bar {
       display: flex;
       align-items: center;
       justify-content: space-between;
       gap: 20px;
       margin-bottom: 28px;
     }

     .brand {
       display: flex;
       align-items: center;
       gap: 12px;
       font-weight: 800;
       letter-spacing: -0.03em;
     }

     .brand-mark {
       display: grid;
       width: 42px;
       height: 42px;
       place-items: center;
       color: #ffffff;
       background: linear-gradient(135deg, #111827, #4f46e5);
       border-radius: 14px;
       box-shadow: 0 12px 30px rgba(79, 70, 229, 0.28);
     }

     .library-link {
       color: var(--muted);
       text-decoration: none;
       font-size: 0.95rem;
       font-weight: 650;
     }
